  document.getElementById('usedHours').textContent = used; document.getElementById('totalHours').textContent = weeklyCapacity; document.getElementById('remainingHours').textContent = remaining >= 0 ? text(t('hoursOpen', '{hours}h open'), { hours: remaining }) : text(t('hoursOver', '{hours}h over'), { hours: Math.abs(remaining) }); document.getElementById('alexHours').textContent = `${founderHours('Alex')}h`; document.getElementById('samHours').textContent = `${founderHours('Sam')}h`; document.getElementById('capacityFill').style.width = `${Math.min(100, used / weeklyCapacity * 100)}%`;
  const status = document.querySelector('.status-chip'); status.textContent = remaining < 0 ? t('overCapacity', 'Over capacity') : remaining <= 3 ? t('nearlyFull', 'Nearly full') : t('onTrack', 'On track'); status.style.background = remaining < 0 ? '#f3d8d4' : remaining <= 3 ? '#f3ead0' : '#e1eed4';
