  document.getElementById('capacityPlannedHint').textContent = `${planned}h`;
  document.getElementById('capacityBalanceHint').textContent = remaining >= 0 ? text(t('hoursUnallocated', '{hours}h unallocated'), { hours: remaining }) : text(t('hoursOverCapacity', '{hours}h over capacity'), { hours: Math.abs(remaining) });
  const cashField = document.getElementById('cashInput'), burnField = document.getElementById('burnInput');
