document.getElementById('openFocus').addEventListener('click', () => { document.getElementById('focusInput').value = focus.title; document.getElementById('focusDescInput').value = focus.description; document.getElementById('focusProgressInput').value = focus.progress; openDialog('focusModal'); });
document.getElementById('focusForm').addEventListener('submit', event => { event.preventDefault(); focus = { title: document.getElementById('focusInput').value.trim(), description: document.getElementById('focusDescInput').value.trim(), progress: document.getElementById('focusProgressInput').value.trim() }; save('pulseboard-focus', focus); updateFocus(); document.getElementById('focusModal').close(); notify(t('weeklyFocusUpdated', 'Weekly focus updated.')); });
document.getElementById('openSettings').addEventListener('click', () => { document.getElementById('capacityInput').value = weeklyCapacity; openDialog('settingsModal'); });
document.getElementById('settingsForm').addEventListener('submit', event => { event.preventDefault(); weeklyCapacity = Number(document.getElementById('capacityInput').value); save('pulseboard-capacity', weeklyCapacity); updateCapacity(); document.getElementById('settingsModal').close(); notify(t('weeklyCapacityUpdated', 'Weekly capacity updated.')); });
document.getElementById('openSearch').addEventListener('click', () => { openDialog('searchModal'); document.getElementById('searchInput').focus(); });
document.getElementById('searchInput').addEventListener('input', event => { const term = event.target.value.trim().toLowerCase(), results = document.getElementById('searchResults'); if (!term) { results.innerHTML = `<p>${t('startTypingSearch', 'Start typing to search your work.')}</p>`; return; } const matches = tasks.filter(task => `${task.title} ${task.initiative}`.toLowerCase().includes(term)).slice(0, 6); results.innerHTML = matches.length ? matches.map(task => `<button type="button" class="search-result" data-task-id="${task.id}"><b>${escapeHtml(tr(task.title))}</b><small>${escapeHtml(tr(task.initiative))} · ${task.done ? t('completed', 'Completed') : t('open', 'Open')} · ${task.hours}h</small></button>`).join('') : `<p>${t('noSearchResults', 'No work matches that search.')}</p>`; document.querySelectorAll('.search-result[data-task-id]').forEach(result => result.addEventListener('click', () => { document.getElementById('searchModal').close(); document.querySelector('[data-view="work"]').click(); notify(t('openedWorkList', 'Opened work list.')); })); });
document.getElementById('searchInput').addEventListener('keydown', event => { if (event.key !== 'Enter') return; const firstResult = document.querySelector('.search-result[data-task-id]'); if (!firstResult) return; event.preventDefault(); firstResult.click(); });
document.getElementById('openNotifications').addEventListener('click', () => notify(t('decisionDueNotification', 'One decision is due Thursday: Data strategy for pilot.')));
document.getElementById('openFinance').addEventListener('click', () => { document.getElementById('cashInput').value = finance.cash; document.getElementById('burnInput').value = finance.burn; openDialog('financeModal'); });
document.getElementById('financeForm').addEventListener('submit', event => { event.preventDefault(); finance = { cash: Number(document.getElementById('cashInput').value), burn: Number(document.getElementById('burnInput').value) }; save('pulseboard-finance', finance); updateFinance(); document.getElementById('financeModal').close(); notify(t('financialsUpdated', 'Financial snapshot updated.')); });
document.getElementById('openReview').addEventListener('click', () => { const review = getSaved('pulseboard-review', {}); document.getElementById('reviewWin').value = review.win || ''; document.getElementById('reviewNext').value = review.next || ''; openDialog('reviewModal'); });
document.getElementById('reviewForm').addEventListener('submit', event => { event.preventDefault(); save('pulseboard-review', { win: document.getElementById('reviewWin').value.trim(), next: document.getElementById('reviewNext').value.trim() }); document.getElementById('reviewModal').close(); notify(t('reviewSaved', 'Friday review saved for your founders.')); });
document.querySelectorAll('.knowledge-card').forEach(card => card.addEventListener('click', () => renderKnowledgePreview(card.dataset.knowledge)));
['statusFilter', 'ownerFilter', 'initiativeFilter'].forEach(id => document.getElementById(id).addEventListener('change', renderTasks));
document.querySelectorAll('.nav-item[data-view],.mobile-tab[data-view]').forEach(button => button.addEventListener('click', () => { const view = button.dataset.view; document.querySelectorAll('.nav-item[data-view],.mobile-tab[data-view]').forEach(item => { const isActive = item.dataset.view === view; item.classList.toggle('active', isActive); if (isActive) item.setAttribute('aria-current', 'page'); else item.removeAttribute('aria-current'); }); document.querySelectorAll('.view').forEach(viewElement => viewElement.classList.remove('active-view')); document.getElementById(view).classList.add('active-view'); document.getElementById('viewCrumb').textContent = view === 'overview' ? t('thisWeek', 'THIS WEEK') : currentTheme().nav[view][1].toUpperCase(); setMobileNavigation(false); window.scrollTo({ top: 0, behavior: 'smooth' }); }));
document.getElementById('workspaceSwitcher').addEventListener('click', () => { const menu = document.getElementById('workspaceMenu'), shouldOpen = menu.hidden; closeMenus(); menu.hidden = !shouldOpen; document.getElementById('workspaceSwitcher').setAttribute('aria-expanded', String(shouldOpen)); });
document.getElementById('accountSwitcher').addEventListener('click', () => { const menu = document.getElementById('accountMenu'), shouldOpen = menu.hidden; closeMenus(); menu.hidden = !shouldOpen; document.getElementById('accountSwitcher').setAttribute('aria-expanded', String(shouldOpen)); });
document.getElementById('workspaceForm').addEventListener('submit', event => { event.preventDefault(); const name = document.getElementById('workspaceInput').value.trim(), design = document.getElementById('workspaceDesign').value; if (!name) return; const id = `${name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '') || 'workspace'}-${Date.now().toString(36)}`, description = workspaceDescriptionByDesign[design], group = workspaceGroupByDesign[design], stage = workspaceStageByDesign[design], capacity = workspaceCapacityByDesign[design]; workspaces = [...workspaces, { id, name, description, group, icon: name.charAt(0).toUpperCase(), design, stage, capacity }]; saveGlobal('pulseboard-workspaces', workspaces); event.target.reset(); document.getElementById('workspaceModal').close(); loadWorkspace(id); });
document.getElementById('accountForm').addEventListener('submit', event => { event.preventDefault(); const name = document.getElementById('accountNameInput').value.trim(), role = document.getElementById('accountRoleInput').value.trim(); if (!name || !role) return; accounts = accounts.map(account => account.id === activeAccountId ? { ...account, name, role, avatar: name.charAt(0).toUpperCase() } : account); saveGlobal('pulseboard-accounts', accounts); updateAccountUI(); document.getElementById('accountModal').close(); notify(t('activeProfileUpdated', 'Active profile updated.')); });
document.addEventListener('click', event => { if (!document.getElementById('workspaceArea').contains(event.target) && !document.getElementById('accountArea').contains(event.target)) closeMenus(); });
document.getElementById('viewAllWork').addEventListener('click', () => document.querySelector('[data-view="work"]').click());
document.querySelector('.mobile-menu').addEventListener('click', () => setMobileNavigation(!document.querySelector('.sidebar').classList.contains('mobile-open')));
document.getElementById('mobileNavBackdrop').addEventListener('click', () => setMobileNavigation(false));
document.addEventListener('keydown', event => { if (event.key === 'Escape') { closeMenus(); setMobileNavigation(false); } if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === 'k') { event.preventDefault(); document.getElementById('openSearch').click(); } });
window.addEventListener('resize', () => { if (window.innerWidth > 620) setMobileNavigation(false); });
document.querySelectorAll('.modal-close').forEach(button => { button.type = 'button'; button.addEventListener('click', () => button.closest('dialog').close()); });
document.getElementById('taskHours').addEventListener('change', updateDialogSummaries);
document.getElementById('capacityInput').addEventListener('input', () => { const planned = getPlannedHours(), proposed = Number(document.getElementById('capacityInput').value) || weeklyCapacity, remaining = proposed - planned; document.getElementById('capacityBalanceHint').textContent = remaining >= 0 ? text(t('hoursUnallocated', '{hours}h unallocated'), { hours: remaining }) : text(t('hoursOverCapacity', '{hours}h over capacity'), { hours: Math.abs(remaining) }); });
['cashInput', 'burnInput'].forEach(id => document.getElementById(id).addEventListener('input', updateDialogSummaries));
document.querySelectorAll('dialog').forEach(dialog => dialog.addEventListener('click', event => { if (event.target === dialog) dialog.close(); }));
document.getElementById('languageToggle').addEventListener('click', () => { interfaceLanguage = interfaceLanguage === 'en' ? 'vi' : 'en'; localStorage.setItem('ventureboard-language', interfaceLanguage); refreshLocalizedInterface(); notify(interfaceLanguage === 'vi' ? 'Đã bật giao diện tiếng Việt.' : 'English interface enabled.'); });
document.getElementById('themeToggle').addEventListener('click', () => { colorTheme = colorTheme === 'light' ? 'dark' : 'light'; localStorage.setItem('ventureboard-color-theme', colorTheme); applyColorTheme(); applyInterfaceLanguage(); notify(colorTheme === 'dark' ? t('darkThemeEnabled', 'Dark theme enabled.') : t('lightThemeEnabled', 'Light theme enabled.')); });
applyColorTheme(); applyInterfaceLanguage(); updateWorkspaceUI(); updateAccountUI(); renderTasks(); updateCapacity(); updateFocus(); updateFinance(); updateDialogSummaries(); renderProjects(); renderKnowledgePreview('Customer insights'); renderDecisions();
